from rules import choose


def solve(data):
    return choose(data)

def choose(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    best_score = None
    best_versions = None
    initial_constraints = {
        name: (interval[0], interval[1])
        for name, interval in roots.items()
    }

    def active_dependencies(row):
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(assigned):
        state = {}

        def visit(name):
            color = state.get(name, 0)
            if color == 1:
                return False
            if color == 2:
                return True
            state[name] = 1
            for dep in active_dependencies(assigned[name]):
                target = dep['name']
                if target not in assigned or not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in assigned)

    def search(assigned, needed, constraints):
        nonlocal best_score, best_versions

        unresolved = needed - assigned.keys()
        if not unresolved:
            if not is_acyclic(assigned):
                return
            score = tuple(
                assigned[name]['version'] if name in assigned else -1
                for name in names
            )
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {
                    name: row['version'] for name, row in assigned.items()
                }
            return

        name = min(unresolved)
        low, high = constraints.get(name, (None, None))

        for row in packages[name]:
            version = row['version']
            if low is not None and version < low:
                continue
            if high is not None and version > high:
                continue
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_needed = set(needed)
            next_constraints = dict(constraints)
            valid = True

            for dep in active_dependencies(row):
                dep_name = dep['name']
                if dep_name not in packages:
                    valid = False
                    break

                dep_low, dep_high = next_constraints.get(
                    dep_name, (None, None)
                )
                dep_low = max(dep_low, dep['min']) if dep_low is not None else dep['min']
                dep_high = min(dep_high, dep['max']) if dep_high is not None else dep['max']
                if dep_low > dep_high:
                    valid = False
                    break

                next_constraints[dep_name] = (dep_low, dep_high)
                next_needed.add(dep_name)
                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]['version']
                    if not (dep_low <= dep_version <= dep_high):
                        valid = False
                        break

            if valid:
                search(next_assigned, next_needed, next_constraints)

    search({}, set(roots), initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
